const state={page:"overview",system:"Jita",selectedSystem:"Sobaseki",analysisOrigin:"location",maxJumps:5,tier:2,planet:null,product:"mechanical-parts",onlyEligible:true,risk:"Moderate",hauling:"Low",help:{scope:"nearby",jumps:5,tier:"all",completeOnly:true},fit:{ccuLevel:4,linkReserve:10,heads:6,colonyLimit:6},layout:{planetId:null,zoneKm:600,linkRate:.15,positions:{}},logistics:{pocoRate:10,utilization:75,cargoCapacity:10000,cargoBuffer:15,costPerJump:0,routePreference:"Shorter",esiStatus:"idle",esiRoute:[],esiError:""},market:{regionId:10000002,saleMode:"instant",sourcing:"local",brokerFee:3,salesTax:3.6,prices:{},status:"idle",compareStatus:"idle",error:""},colony:{system:"Sobaseki",selected:[],roles:{},product:"mechanical-parts",cadence:3,style:"balanced",generated:false}};
const piData=window.PI_DATA;
const systemByName=new Map(piData.systems.map(s=>[s.name.toLowerCase(),s]));
const systemById=new Map(piData.systems.map(s=>[s.id,s]));
const productById=new Map(piData.products.map(p=>[p.id,p]));
const productByTypeId=new Map(piData.products.map(p=>[p.typeId,p]));
const planetById=new Map(piData.planets.map(p=>[p.id,p]));
const metric=(l,v,s="",c="")=>`<div class="panel metric"><div class="metric-label">${l}</div><div class="metric-value ${c}">${v}</div><div class="metric-sub">${s}</div></div>`;
const panel=(t,b,e="")=>`<section class="panel"><div class="panel-header"><div class="panel-title">${t}</div>${e}</div><div class="panel-body">${b}</div></section>`;
const header=(e,t,d,b="")=>`<div class="page-header"><div><div class="eyebrow">${e}</div><h1>${t}</h1><p class="page-description">${d}</p></div><div class="toolbar">${b}</div></div>`;
const footer=()=>`<div class="footer-status"><span><strong>DATA:</strong> CCP SDE</span><span><strong>BUILD:</strong> ${piData.metadata.sdeBuild}</span><span><strong>SYSTEMS:</strong> ${piData.metadata.counts.systems.toLocaleString()}</span><span><strong>ESI:</strong> Public adapter</span><span><strong>LOGIN:</strong> Not required</span></div>`;

function getSystem(name){return systemByName.get(String(name||"").trim().toLowerCase())}
function displayedSecurity(s){return Number(s.security).toFixed(1)}
function riskLabel(s){return s.security>=.8?"Low":s.security>=.5?"Moderate":s.security>0?"High":"Extreme"}
function matchingSystems(value){const q=value.trim().toLowerCase();if(!q)return ["Jita","Amarr","Dodixie","Rens","Hek","Atlangeins"].filter(getSystem);const prefix=[],contains=[];for(const name of piData.systemIndex){const lower=name.toLowerCase();if(lower.startsWith(q))prefix.push(name);else if(lower.includes(q))contains.push(name)}return prefix.concat(contains).slice(0,8)}
function resolveSystemName(value){const exact=getSystem(value);return exact?exact.name:(matchingSystems(value)[0]||"")}
function systemSearchField(id,value,label){return `<div class="field system-search"><label>${label}</label><input id="${id}" value="${value}" aria-label="${label}" autocomplete="off" spellcheck="false"><div class="system-suggestions" data-suggestions-for="${id}" hidden></div></div>`}
function distancesFrom(name,max=10){const home=getSystem(name),distances=new Map();if(!home)return distances;distances.set(home.id,0);const queue=[home.id];for(let i=0;i<queue.length;i++){const id=queue[i],d=distances.get(id);if(d>=max)continue;for(const next of systemById.get(id).neighbors){if(!distances.has(next)){distances.set(next,d+1);queue.push(next)}}}return distances}
function distanceBetween(from,to){const target=getSystem(to);return target?(distancesFrom(from,100).get(target.id)??null):null}
function routeBetween(from,to){const start=getSystem(from),target=getSystem(to);if(!start||!target)return [];if(start.id===target.id)return [start];const parents=new Map([[start.id,null]]),queue=[start.id];for(let i=0;i<queue.length;i++){const id=queue[i];for(const next of systemById.get(id).neighbors){if(parents.has(next))continue;parents.set(next,id);if(next===target.id){const path=[];for(let current=next;current!==null;current=parents.get(current))path.push(systemById.get(current));return path.reverse()}queue.push(next)}}return []}
function nearbySystems(name,max,eligibleOnly=false,planet=null){return [...distancesFrom(name,max)].map(([id,distance])=>({...systemById.get(id),distance})).filter(s=>!eligibleOnly||!s.restricted).filter(s=>!planet||s.planets[planet]).sort((a,b)=>a.distance-b.distance||b.security-a.security||a.name.localeCompare(b.name))}
function systemResources(system){const result=new Set();Object.keys(system.planets).forEach(id=>(planetById.get(id)?.resources||[]).forEach(r=>result.add(r)));return result}
function coverage(system,product){const available=systemResources(system),required=product.rawInputs||[],found=required.filter(r=>available.has(r)),factoryOk=product.tier!==4||Boolean(system.planets.barren||system.planets.temperate);return {found,missing:required.filter(r=>!available.has(r)),ratio:required.length?found.length/required.length:1,factoryOk,complete:!system.restricted&&factoryOk&&required.every(r=>available.has(r))}}
function requiredPlanetTypes(system,product){const remaining=new Set(product.rawInputs||[]),selected=[];const candidates=Object.keys(system.planets).map(typeId=>({typeId,resources:planetById.get(typeId)?.resources||[]}));while(remaining.size&&selected.length<6){let best=null,covers=[];for(const candidate of candidates.filter(c=>!selected.includes(c.typeId))){const found=candidate.resources.filter(r=>remaining.has(r));if(found.length>covers.length){best=candidate;covers=found}}if(!best||!covers.length)break;selected.push(best.typeId);covers.forEach(r=>remaining.delete(r))}return {types:selected,missing:[...remaining]}}
function planetCounts(system){return Object.entries(system.planets).map(([id,count])=>{const p=planetById.get(id);return `<span class="planet-count"><i style="--planet:${p.color}"></i>${p.name} ×${count}</span>`}).join("")}
function restrictedBanner(system){return system?.restricted?`<div class="restricted-banner"><div class="restricted-icon">!</div><div><strong>Planetary Industry unavailable in ${system.name}</strong><span>${system.restrictionReason}. It can remain your logistics home while you compare eligible neighbors.</span></div><span class="tag danger">NO PI</span></div>`:""}
function systemTable(items){return `<div class="table-wrap"><table class="systems-table"><thead><tr><th>SYSTEM</th><th>JUMPS</th><th>SEC</th><th>REGION</th><th>PLANETS</th><th>PI</th><th></th></tr></thead><tbody>${items.map(s=>`<tr class="analysis-row" data-analyze-system="${s.name}" tabindex="0"><td><strong>${s.name}</strong></td><td>${s.distance===undefined?"—":`<b class="jump-badge">${s.distance}</b>`}</td><td><span class="security sec-${s.security>=.8?"high":s.security>=.5?"mid":"low"}">${displayedSecurity(s)}</span></td><td>${s.region}</td><td>${s.planetTotal}</td><td>${s.restricted?'<span class="tag danger">RESTRICTED</span>':'<span class="tag good">ELIGIBLE</span>'}</td><td><button class="row-action">ANALYZE →</button></td></tr>`).join("")||'<tr><td colspan="7"><div class="empty">No connected systems found.</div></td></tr>'}</tbody></table></div>`}

function overview(){const home=getSystem(state.system)||getSystem("Jita"),nearby=nearbySystems(home.name,3,true).slice(0,6);return `${header("OPERATIONS / OVERVIEW","PI Operations Console","Choose a real New Eden system, inspect its actual planets, and turn a product target into a starter plan.",'<button class="btn primary" data-page-link="productionHelp">OPEN PRODUCTION HELP</button>')}<div class="grid grid-4" style="margin-bottom:12px">${metric("HOME SYSTEM",home.name,`${home.region} // ${displayedSecurity(home)}`,"accent")}${metric("PI STATUS",home.restricted?"RESTRICTED":"AVAILABLE",home.restrictionReason||"Colonies permitted",home.restricted?"red":"green")}${metric("SDE SYSTEMS",piData.metadata.counts.systems.toLocaleString(),`${piData.metadata.counts.planets.toLocaleString()} planets`)}${metric("PRIVATE DATA","NONE","No character login or token","green")}</div>${restrictedBanner(home)}<div class="grid grid-2" style="margin-bottom:12px">${panel("DATA FOUNDATION",`<div class="source-map"><div><span>SYSTEMS</span><strong>Names, IDs, regions, security</strong><b class="tag good">LOADED</b></div><div><span>PLANETS</span><strong>Actual types in every system</strong><b class="tag good">LOADED</b></div><div><span>ROUTES</span><strong>${piData.metadata.counts.stargateLinks.toLocaleString()} stargate links</strong><b class="tag good">LOADED</b></div><div><span>PRODUCTION</span><strong>${piData.metadata.counts.schematics} schematics</strong><b class="tag good">LOADED</b></div></div>`)}${panel("SAFE PUBLIC-DATA MODE",'<div class="privacy-note"><strong>NO SSO</strong><span>CCP public data powers the planner. Public ESI is optional for current lookups.</span><b class="tag good">LOCAL FIRST</b></div><div class="code-note">POCO tax and market prices are kept separate because the public SDE does not contain them.</div>')}</div>${panel(`ELIGIBLE SYSTEMS WITHIN 3 JUMPS OF ${home.name}`,systemTable(nearby))}<div style="height:12px"></div>${footer()}`}

function locationPage(){const home=getSystem(state.system)||getSystem("Jita"),results=nearbySystems(home.name,state.maxJumps).slice(0,100);return `${header("OPERATIONS / LOCATION","System Explorer","Autocomplete covers New Eden. Nearby searches follow real SDE stargate connections.",'<button class="btn primary" data-action="analyzeLocation">ANALYZE SYSTEM</button>')}${panel("LOCATION INPUT",`<div class="form-grid">${systemSearchField("locationSystem",home.name,"SYSTEM TO ANALYZE")}<div class="field"><label>SEARCH RANGE</label><select id="locationRange">${[0,1,3,5,10,20].map(n=>`<option value="${n}" ${state.maxJumps===n?"selected":""}>${n?`${n} jumps`:"This system only"}</option>`).join("")}</select></div><div class="field"><label>GOAL</label><select><option>Balanced planet coverage</option><option>Lowest hauling distance</option><option>Lower security potential</option></select></div></div>`)}<div style="height:12px"></div>${restrictedBanner(home)}${panel(`REAL STARGATE RESULTS // ${results.length}`,systemTable(results))}<div style="height:12px"></div>${footer()}`}

function planetsPage(){return `${header("REFERENCE / PLANETS","Planet Explorer","Each planet type supplies five P0 resources. Actual system composition comes from CCP's SDE.")}<div class="grid grid-4">${piData.planets.map(p=>panel(p.name,`<div class="planet-reference" style="--planet:${p.color}"><span class="planet-disc"></span><div>${p.resources.map(r=>`<b>${r}</b>`).join("")}</div></div>`)).join("")}</div><div style="height:12px"></div>${footer()}`}
function resourcesPage(){return `${header("REFERENCE / RESOURCES","P0 Resource Index","The 15 extractable resources and every planet type that provides them.")}<div class="grid grid-3">${piData.products.filter(p=>p.tier===0).map(p=>panel(p.name,`<div class="product-list">${p.planets.map(id=>{const planet=planetById.get(id);return `<span class="product-pill"><i style="--planet:${planet.color}"></i>${planet.name}</span>`}).join("")}</div>`)).join("")}</div><div style="height:12px"></div>${footer()}`}
function productionPage(){return `${header("REFERENCE / PRODUCTION","Production Schematics","Browse verified SDE inputs, outputs, quantities, and processor cycle times.")}<div class="tier-tabs">${[0,1,2,3,4].map(t=>`<button class="tier-tab ${state.tier===t?"active":""}" data-tier="${t}"><span>P${t}</span><small>${piData.products.filter(p=>p.tier===t).length} items</small></button>`).join("")}</div><div class="product-grid">${piData.products.filter(p=>p.tier===state.tier).map(p=>`<button class="product-card ${state.product===p.id?"selected":""}" data-product="${p.id}"><span class="tier-chip">P${p.tier}</span><strong>${p.name}</strong><small>${p.inputs.length?p.inputs.join(" + "):"Extracted P0 resource"}</small>${p.cycleTime?`<em>${p.outputQuantity} per ${p.cycleTime/60} min cycle</em>`:""}</button>`).join("")}</div><div style="height:12px"></div>${footer()}`}

function browserPage(){const product=productById.get(state.product)||piData.products.find(p=>p.tier===state.tier),home=getSystem(state.system)||getSystem("Jita"),results=nearbySystems(home.name,state.maxJumps,state.onlyEligible,state.planet).slice(0,100),chosen=planetById.get(state.planet);return `${header("DISCOVER / PRODUCTION BROWSER","Production Browser","Browse P0–P4 and compare actual planet mixes around your home.",'<button class="btn" data-action="clearFilters">CLEAR FILTERS</button>')}<section class="finder-bar panel"><div class="grow"><div class="input-action system-input-action">${systemSearchField("homeSystem",home.name,"HOME SYSTEM")}<button class="btn primary" data-action="setHome">SET HOME</button></div></div><div class="field jump-field"><label>MAX JUMPS <strong id="jumpValue">${state.maxJumps}</strong></label><input id="maxJumps" type="range" min="0" max="20" value="${state.maxJumps}"></div><label class="check"><input id="onlyEligible" type="checkbox" ${state.onlyEligible?"checked":""}> PI-eligible only</label></section>${restrictedBanner(home)}<div class="browser-layout"><div class="browser-main">${panel("SELECT A PLANET TYPE",`<div class="planet-orbit">${piData.planets.map(p=>`<button class="planet-node ${state.planet===p.id?"selected":""}" data-planet="${p.id}" style="--planet:${p.color}"><span class="planet-disc"></span><strong>${p.name}</strong><small>5 raw resources</small></button>`).join("")}</div>${chosen?`<div class="resource-strip"><span>RAW RESOURCES</span>${chosen.resources.map(r=>`<b>${r}</b>`).join("")}</div>`:'<div class="selection-hint">Select a planet to inspect resources and filter systems.</div>'}`)}<div style="height:12px"></div>${panel("BROWSE PRODUCTS",`<div class="tier-tabs">${[0,1,2,3,4].map(t=>`<button class="tier-tab ${state.tier===t?"active":""}" data-tier="${t}"><span>P${t}</span><small>${piData.products.filter(p=>p.tier===t).length} items</small></button>`).join("")}</div><div class="product-grid">${piData.products.filter(p=>p.tier===state.tier).map(p=>`<button class="product-card ${state.product===p.id?"selected":""}" data-product="${p.id}"><span class="tier-chip">P${p.tier}</span><strong>${p.name}</strong><small>${p.inputs.length?p.inputs.join(" + "):"Extracted resource"}</small></button>`).join("")}</div>`)}</div><aside class="chain-panel panel"><div class="panel-header"><div class="panel-title">SELECTED PRODUCTION</div><span class="tier-chip">P${product.tier}</span></div><div class="panel-body"><div class="chain-name">${product.name}</div><div class="chain-label">DIRECT INPUTS</div><div class="chain-inputs">${product.inputs.length?product.inputs.map(i=>`<div><span>${i}</span><b>→</b></div>`).join(""):'<div><span>Planet extraction</span><b>→</b></div>'}</div><div class="chain-output">${product.name}</div><div class="chain-label">FULL RAW REQUIREMENT</div><div class="resource-strip compact">${product.rawInputs.map(r=>`<b>${r}</b>`).join("")}</div><button class="btn primary full" data-page-link="productionHelp">CHECK WHAT IS FEASIBLE</button></div></aside></div><div style="height:12px"></div>${panel(`NEARBY SYSTEM COMPARISON // FIRST ${results.length}`,`<div class="table-wrap"><table><thead><tr><th>SYSTEM</th><th>JUMPS</th><th>SEC</th><th>PLANET MIX</th><th>RAW COVERAGE</th><th></th></tr></thead><tbody>${results.map(s=>{const c=coverage(s,product);return `<tr class="analysis-row" data-analyze-system="${s.name}" tabindex="0"><td><strong>${s.name}</strong><br><span>${s.region}</span></td><td><b class="jump-badge">${s.distance}</b></td><td>${displayedSecurity(s)}</td><td><div class="planet-mix">${planetCounts(s)}</div></td><td><span class="fit-score">${Math.round(c.ratio*100)}%</span></td><td><button class="row-action">ANALYZE →</button></td></tr>`}).join("")||'<tr><td colspan="6"><div class="empty">No systems match these filters.</div></td></tr>'}</tbody></table></div>`)}<div style="height:12px"></div>${footer()}`}

function systemAnalysisPage(){const system=getSystem(state.selectedSystem)||getSystem(state.system),distance=distanceBetween(state.system,system.name),available=piData.products.filter(p=>coverage(system,p).complete),tiers=[0,1,2,3,4].map(t=>{const products=piData.products.filter(p=>p.tier===t),count=products.filter(p=>coverage(system,p).complete).length;return {t,count,total:products.length,value:Math.round(count/products.length*100)}});return `${header("LOCATION / SYSTEM ANALYSIS",system.name,`${system.region} // ${displayedSecurity(system)} security // ${distance===null?"no static gate route":`${distance} jumps`} from ${state.system}`,`<button class="btn" data-action="backFromAnalysis">← BACK</button><button class="btn primary" data-action="useSystem" ${system.restricted?"disabled":""}>PLAN HERE</button>`)}${restrictedBanner(system)}<div class="grid grid-4" style="margin-bottom:12px">${metric("PI STATUS",system.restricted?"RESTRICTED":"ELIGIBLE",system.restrictionReason||"Colonies permitted",system.restricted?"red":"green")}${metric("DISTANCE",distance===null?"NO ROUTE":`${distance} JUMPS`,`From ${state.system}`,"accent")}${metric("PLANETS",system.planetTotal,`${Object.keys(system.planets).length} types`)}${metric("COMPLETE PRODUCTS",available.length,`of ${piData.products.length} P0–P4 items`,"accent")}</div><div class="analysis-layout"><div>${panel("ACTUAL PLANET COMPOSITION",`<div class="analysis-planets">${Object.entries(system.planets).map(([id,count])=>{const p=planetById.get(id);return `<button class="analysis-planet" data-planet="${id}" style="--planet:${p.color}"><span class="planet-disc"></span><div><strong>${p.name}</strong><small>${p.resources.join(" • ")}</small></div><b>×${count}</b></button>`}).join("")}</div>`)}<div style="height:12px"></div>${panel("COMPLETE LOCAL PRODUCTION COVERAGE",`<div class="coverage-bars">${tiers.map(x=>`<div class="coverage-bar"><div><span>P${x.t}</span><small>${x.count} of ${x.total} products</small><b>${x.value}%</b></div><div class="progress"><i style="width:${x.value}%"></i></div></div>`).join("")}</div>`)}</div><aside>${panel("SYSTEM FIT",`<div class="analysis-facts"><div><span>RAW RESOURCES</span><b>${systemResources(system).size}/15</b></div><div><span>POCO TAX</span><b>PLAYER INPUT</b></div><div><span>ROUTE RISK</span><b>${riskLabel(system).toUpperCase()}</b></div><div><span>DATA STATUS</span><b>SDE VERIFIED</b></div></div><button class="btn primary full" data-page-link="productionHelp">VIEW PRODUCTION HELP →</button>`)}</aside></div><div style="height:12px"></div>${panel("PRODUCTS POSSIBLE FROM LOCAL EXTRACTION",`<div class="product-list">${available.map(p=>`<button data-product="${p.id}" class="product-pill"><span>P${p.tier}</span>${p.name}</button>`).join("")||'<div class="empty">No complete local extraction chains.</div>'}</div>`)}<div style="height:12px"></div>${footer()}`}

function helpSystems(){const home=getSystem(state.system)||getSystem("Jita");return state.help.scope==="home"?[{...home,distance:0}]:nearbySystems(home.name,state.help.jumps,true)}
function helpResults(){const systems=helpSystems();return piData.products.filter(p=>p.tier>=1&&(state.help.tier==="all"||p.tier===Number(state.help.tier))).map(product=>{const ranked=systems.map(system=>({system,c:coverage(system,product)})).sort((a,b)=>Number(b.c.complete)-Number(a.c.complete)||b.c.ratio-a.c.ratio||a.system.distance-b.system.distance);return {product,best:ranked[0],completeCount:ranked.filter(x=>x.c.complete).length}}).filter(x=>x.best&&(!state.help.completeOnly||x.best.c.complete)).sort((a,b)=>a.product.tier-b.product.tier||a.product.name.localeCompare(b.product.name))}
function productionHelpPage(){const home=getSystem(state.system)||getSystem("Jita"),systems=helpSystems(),results=helpResults();return `${header("GUIDED PLANNING / PRODUCTION HELP","What Can I Make Here?","Check your home system or a real jump range, then generate a beginner-friendly colony plan.",'<button class="btn" data-page-link="browser">BROWSE ALL PRODUCTS</button>')}<div class="privacy-note"><strong>PUBLIC DATA ONLY</strong><span>Local CCP SDE and static stargates. No character login or location tracking.</span><b class="tag good">NO SSO</b></div>${panel("1 // CHOOSE THE AREA TO CHECK",`<div class="help-controls"><div class="input-action system-input-action">${systemSearchField("helpSystem",home.name,"HOME OR REFERENCE SYSTEM")}<button class="btn primary" data-action="applyHelpSystem">APPLY</button></div><div class="segmented"><button data-help-scope="home" class="${state.help.scope==="home"?"active":""}">ONLY ${home.name.toUpperCase()}</button><button data-help-scope="nearby" class="${state.help.scope==="nearby"?"active":""}">WITHIN JUMPS</button></div><div class="field jump-field"><label>MAX JUMPS <strong id="helpJumpValue">${state.help.jumps}</strong></label><input id="helpJumps" type="range" min="1" max="20" value="${state.help.jumps}" ${state.help.scope==="home"?"disabled":""}></div></div>`)}<div style="height:12px"></div>${restrictedBanner(state.help.scope==="home"?home:null)}<div class="grid grid-4" style="margin-bottom:12px">${metric("AREA",state.help.scope==="home"?home.name:`${state.help.jumps} JUMPS`,state.help.scope==="home"?"One system":`Centered on ${home.name}`,"accent")}${metric("SYSTEMS CHECKED",systems.length,"PI-eligible candidates")}${metric("RESULTS",results.length,"Current filters","green")}${metric("CONFIDENCE","SDE VERIFIED","Abundance and POCO excluded","accent")}</div>${panel("2 // CHOOSE A PRODUCTION LEVEL",`<div class="help-filter-row"><div class="tier-tabs">${["all",1,2,3,4].map(t=>`<button class="tier-tab ${String(state.help.tier)===String(t)?"active":""}" data-help-tier="${t}"><span>${t==="all"?"ALL":`P${t}`}</span><small>${t==="all"?"Products":"Tier"}</small></button>`).join("")}</div><label class="check"><input id="helpCompleteOnly" type="checkbox" ${state.help.completeOnly?"checked":""}> Complete local chains only</label></div>`)}<div style="height:12px"></div>${panel(`3 // FEASIBLE PRODUCTION // ${results.length} RESULTS`,results.length?`<div class="help-results">${results.map(({product,best,completeCount})=>{const plan=requiredPlanetTypes(best.system,product),names=plan.types.map(id=>planetById.get(id).name);return `<article class="help-card ${best.c.complete?"complete":"partial"}"><div class="help-card-head"><span class="tier-chip">P${product.tier}</span><div><strong>${product.name}</strong><small>${product.inputs.join(" + ")}</small></div><b class="${best.c.complete?"green":"yellow"}">${best.c.complete?"COMPLETE":"PARTIAL"}</b></div><div class="help-best"><span>BEST MATCH</span><strong>${best.system.name}</strong><small>${best.system.distance} jumps // ${displayedSecurity(best.system)} sec // ${Math.round(best.c.ratio*100)}% raw coverage</small></div><div class="help-planets"><span>PLANETS NEEDED</span>${names.map(n=>`<b>${n}</b>`).join("")}${plan.missing.length?`<em>Missing: ${plan.missing.join(", ")}</em>`:""}</div><div class="help-card-foot"><span>${completeCount} complete system${completeCount===1?"":"s"} in range</span><button class="btn primary" data-auto-plan="${product.id}" data-plan-system="${best.system.name}" ${best.c.complete?"":"disabled"}>CREATE RECOMMENDED PLAN →</button></div></article>`}).join("")}</div>`:`<div class="empty"><strong>NO COMPLETE CHAINS MATCH</strong><br>${home.restricted&&state.help.scope==="home"?`${home.name} is PI restricted. Choose “Within jumps” to compare nearby systems.`:"Increase the jump range, choose another tier, or turn off complete-only."}</div>`)}<div style="height:12px"></div>${footer()}`}

function roman(value){const table=[[10,"X"],[9,"IX"],[5,"V"],[4,"IV"],[1,"I"]];let n=Number(value)||1,out="";for(const [amount,symbol] of table)while(n>=amount){out+=symbol;n-=amount}return out}
function colonySystem(){return getSystem(state.colony.system)||nearbySystems(state.system,10,true)[0]}
function colonyPlanetOptions(system){if(system.planetInstances?.length)return system.planetInstances.map((planet,i)=>{const type=planetById.get(planet.typeId);return {id:String(planet.id),typeId:planet.typeId,name:`${system.name} ${roman(planet.index||i+1)}`,radius:planet.radius||0,index:planet.index||i+1,type}});return Object.entries(system.planets).flatMap(([typeId,count])=>{const type=planetById.get(typeId);return Array.from({length:count},(_,i)=>({id:`${typeId}-${i+1}`,typeId,name:`${type.name} ${i+1}`,radius:0,index:i+1,type}))})}
function starterStructures(role){return role==="factory"?["Launchpads ×2","Advanced facilities ×6","Storage buffer"]:role==="hybrid"?["Extractor unit","Basic facilities ×4","Advanced facilities ×2","Launchpad"]:["Extractor unit","Basic facilities ×4","Launchpad"]}
