function routeRows(planet,role,product,fit){const rows=[],hub=fit.counts.launchpad>1?"Launchpads":"Launchpad";if(fit.counts.ecu){rows.push({from:"ECU + heads",to:hub,material:planet.type.resources.join(" / "),note:"Route extracted P0 into the hub"})}if(fit.counts.basic){const outputs=neededProducts(product,1).filter(item=>item.rawInputs.some(raw=>planet.type.resources.includes(raw))).map(item=>item.name);rows.push({from:hub,to:`${fit.counts.basic} Basic processors`,material:"P0 materials",note:"Create incoming routes to each processor"});rows.push({from:"Basic processors",to:hub,material:outputs.join(" / ")||"P1 output",note:"Return every completed P1 batch"})}if(fit.counts.advanced){const outputs=role==="factory"&&product.tier<4?[product.name]:neededProducts(product,Math.max(2,product.tier-1)).map(item=>item.name);rows.push({from:hub,to:`${fit.counts.advanced} Advanced processors`,material:(role==="factory"?product.inputs:outputs).join(" / ")||"P1–P2 inputs",note:"Feed each schematic input separately"});rows.push({from:"Advanced processors",to:hub,material:outputs.join(" / ")||product.name,note:"Return completed output to storage"})}if(fit.counts.highTech){rows.push({from:hub,to:`${fit.counts.highTech} High-Tech processors`,material:product.inputs.join(" / "),note:"Feed all three P3 inputs"});rows.push({from:"High-Tech processors",to:hub,material:product.name,note:"Store completed P4 output"})}return rows}
function operationBalance(selected,product){const fits=selected.map(planet=>{const role=state.colony.roles[planet.id]||"extractor";return {planet,role,fit:fittingForPlanet(planet,role,product)}}),finalKey=product.tier===1?"basic":product.tier===4?"highTech":"advanced",finalCount=fits.filter(item=>product.tier===1?item.role!=="factory":item.role==="factory").reduce((sum,item)=>sum+(item.fit.counts[finalKey]||0),0),direct=(product.inputItems||[]).map(item=>({item,product:productByTypeId.get(item.typeId)})).filter(row=>row.product);if(!direct.length)return {finalCount,rows:[{name:"Extracted P0",needed:finalCount?"Survey dependent":"No processors",capacity:"Planet scan required",ok:null}],ready:finalCount>0};const rows=direct.map(({item,product:input})=>{const key=input.tier===1?"basic":"advanced",pool=fits.filter(entry=>entry.role!=="factory").reduce((sum,entry)=>sum+(entry.fit.counts[key]||0),0),allocated=pool/direct.filter(row=>row.product?.tier===input.tier).length,needed=finalCount*item.quantity*3600/(product.cycleTime||3600),capacity=allocated*input.outputQuantity*3600/(input.cycleTime||3600);return {name:input.name,needed,capacity,facilities:allocated,ok:capacity>=needed}});return {finalCount,rows,ready:finalCount>0&&rows.every(row=>row.ok)}}
