function marketStatus(key){const status=state.market[key];if(status==="loading")return '<div class="market-status loading">CONTACTING CCP // Loading only the requested regional orders…</div>';if(status==="error")return `<div class="market-status error">${state.market.error}</div>`;if(status==="ready")return '<div class="market-status ready">CCP PRICES LOADED // Five best buy and sell levels cached for five minutes.</div>';return '<div class="market-status">No prices loaded yet. Request the selected chain from CCP to see real regional order levels.</div>'}
function compactUnits(value){const units=Math.round(value);if(units>=1000000)return `${(units/1000000).toFixed(units>=10000000?0:1)}m units`;if(units>=1000)return `${(units/1000).toFixed(units>=100000?0:1)}k units`;return `${units.toLocaleString()} units`}
