function marketAssumptions(regions){return panel("MARKET & COST ASSUMPTIONS",`<div class="market-controls"><div class="field"><label>MARKET REGION</label><select id="marketRegion">${regions.map(region=>`<option value="${region.id}" ${region.id===state.market.regionId?"selected":""}>${region.name}</option>`).join("")}</select></div><div class="field"><label>SALE METHOD</label><select id="marketSaleMode"><option value="instant" ${state.market.saleMode==="instant"?"selected":""}>Instant sale — best buy order</option><option value="listed" ${state.market.saleMode==="listed"?"selected":""}>Listed sale — best sell order</option></select></div><div class="field"><label>INPUT SOURCING</label><select id="marketSourcing"><option value="local" ${state.market.sourcing==="local"?"selected":""}>Produced by this colony chain</option><option value="market" ${state.market.sourcing==="market"?"selected":""}>Buy direct inputs at sell price</option></select></div><div class="field"><label>BROKER FEE</label><input id="marketBroker" type="number" min="0" max="100" step="0.1" value="${state.market.brokerFee}"><small>Applied only to listed sales</small></div><div class="field"><label>SALES TAX</label><input id="marketSalesTax" type="number" min="0" max="100" step="0.1" value="${state.market.salesTax}"><small>Enter your effective in-game rate</small></div></div>${marketStatus("status")}`)}
